+package scan
+
+import (
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/future-architect/vuls/config"
+)
+
+func TestEOLWarnings(t *testing.T) {
+	date := func(s string) time.Time { d, _ := time.Parse("2006-01-02", s); return d }
+	tests := []struct {
+		family, release string
+		now             time.Time
+		want            []string
+	}{
+		{config.FreeBSD, "11", date("2021-06-30"), []string{"Standard OS support will be end in 3 months. EOL date: 2021-09-30"}},
+		{config.Ubuntu, "18.04", date("2023-06-01"), []string{"Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended.", "Extended support available until 2028-04-30. Check the vendor site."}},
+		{config.Ubuntu, "14.10", date("2015-07-31"), []string{"Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended.", "Extended support is also EOL. There are many Vulnerabilities that are not detected, Upgrading your OS strongly recommended."}},
+		{config.RedHat, "9", date("2024-01-01"), []string{"Failed to check EOL. Register the issue to https://github.com/future-architect/vuls/issues with the information in 'Family: redhat Release: 9'"}},
+		{config.Raspbian, "9", date("2024-01-01"), nil},
+		{config.Amazon, "2 (Karoo)", date("2025-07-01"), []string{"Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended."}},
+	}
+	for _, tt := range tests {
+		got := eolWarnings(tt.family, tt.release, tt.now)
+		if strings.Join(got, "\n") != strings.Join(tt.want, "\n") {
+			t.Errorf("%s %s: got %q, want %q", tt.family, tt.release, got, tt.want)
+		}
+	}
+}
